package mrpapermoon.whisper.service.internalimport androidx.annotation.CallSuperimport com.google.android.gms.nearby.connection.Payloadimport com.google.android.gms.nearby.connection.PayloadCallbackimport com.google.android.gms.nearby.connection.PayloadTransferUpdateimport io.github.oshai.kotlinlogging.KotlinLoggingimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.MutableSharedFlowinternal abstract class FlowPayloadCallback private constructor(private val delegateFlow: MutableSharedFlow<Event>) :	PayloadCallback(),	Flow<FlowPayloadCallback.Event> by delegateFlow {	protected val logger = KotlinLogging.logger {}	protected constructor() : this(MutableSharedFlow<Event>())	@CallSuper	override fun onPayloadReceived(		endpointId: String,		payload: Payload,	) {		logger.debug { "onPayloadReceived(endpointId: $endpointId, payload: $payload)" }	}	@CallSuper	override fun onPayloadTransferUpdate(endpointId: String, update: PayloadTransferUpdate) {		logger.debug { "onPayloadTransferUpdate(endpointId: $endpointId, update: ${update.dumpString()})" }	}	protected fun emitEvent(event: Event) {		val emit = delegateFlow.tryEmit(event)		if (!emit) {			logger.debug { "We missed the event, should consider incrising buffer space" }		}	}	sealed interface Event {		class OnUnsupportedPayloadReceived : Event		class OnBytesPayloadReceived(val payload: ByteArray) : Event		class OnStreamPayloadReceived(val byteStream: Flow<ByteArray>) : Event	}}